testo:
{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run() -> String:
	var body_name: String = "Enemy"
	var message: String = ""
	if body_name == "Player":
		message = "Benvenuto!"
	else:
		message = "Accesso negato"
	return message
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "`body_name` è "Enemy", quindi la condizione `body_name == "Player"` risulta falsa. Viene eseguito il ramo `else`, che imposta la variabile `message` su "Accesso negato"."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var coins: int = 5
	var coin_value: int = 10
	coins += coin_value
	return coins
",
   "domanda": "Quanto vale `coins` alla fine?",
   "spiegazione": "Partiamo con 5 monete (`coins`). Aggiungiamo il valore dell'oggetto raccolto (`coin_value` che vale 10) usando l'operatore `+=`, ottenendo un totale di 15."
  },
  {
   "codice": "extends RefCounted


func run() -> bool:
	var body_name: String = "Player"
	var has_key: bool = false
	if body_name == "Player" and not has_key:
		return true
	return false
",
   "domanda": "Che valore booleano restituisce `run()`?",
   "spiegazione": "`body_name == "Player"` è vero e `not has_key` è vero (perché `has_key` è falso). Entrambe le condizioni collegate da `and` sono vere, quindi la funzione entra nell' `if` e restituisce `true`."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var collected: bool = false
	var score: int = 100
	if not collected:
		collected = true
		score += 50
	if not collected:
		score += 50
	return score
",
   "domanda": "Quanto vale `score` alla fine?",
   "spiegazione": "All'inizio `collected` è falso, quindi il primo `if` viene eseguito: `collected` diventa vero e `score` sale a 150. Il secondo `if` controlla `not collected`, ma ora `collected` è vero, quindi quel blocco viene saltato. Il punteggio finale è 150."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var zone_active: bool = true
	var zone_message: String = "Tesoro trovato!"
	var current_text: String = ""
	if zone_active:
		current_text = zone_message
	else:
		current_text = ""
	return current_text
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "Dato che `zone_active` è `true`, il blocco `if` assegna correttamente `zone_message` ("Tesoro trovato!") alla variabile `current_text`, che viene poi restituita."
  }
 ]
